	g.idxRawStride = g.nKV * c.IdxDim
	g.idxKStride = g.NBlocks() * c.IdxDim
	g.hK = halloc(nLayers * g.kvStride)
	g.hV = halloc(nLayers * g.kvStride)
	g.hIdxRaw = halloc(nLayers * g.idxRawStride)
	g.hIdxK = halloc(nLayers * g.idxKStride)
