		&handles[0],
		&groupsX[0], &groupsY[0], C.uint32_t(len(dispatches)),
		C.uint32_t(groupsZ), C.uint32_t(iterations), barrierFlag,
		pcPtr, C.uint32_t(pcSize), &start, &end, markPtr)); err != nil {
